CREATE TABLE IF NOT EXISTS p0_users (id VARCHAR(64) PRIMARY KEY, username VARCHAR(32) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, nickname VARCHAR(64) NOT NULL, avatar_id VARCHAR(64), role VARCHAR(20) NOT NULL DEFAULT 'USER', enabled BOOLEAN NOT NULL DEFAULT TRUE, preferences_enabled BOOLEAN NOT NULL DEFAULT FALSE, created_at DATETIME(3) NOT NULL);
CREATE TABLE IF NOT EXISTS p0_sessions (id VARCHAR(64) PRIMARY KEY, user_id VARCHAR(64) NOT NULL, access_hash CHAR(64) UNIQUE NOT NULL, refresh_hash CHAR(64) UNIQUE NOT NULL, csrf_hash CHAR(64) NOT NULL, access_expires DATETIME(3) NOT NULL, expires_at DATETIME(3) NOT NULL, revoked BOOLEAN NOT NULL DEFAULT FALSE, INDEX(user_id));
CREATE TABLE IF NOT EXISTS p0_login_limits (id CHAR(64) PRIMARY KEY, failures INT NOT NULL, window_start DATETIME(3) NOT NULL);
CREATE TABLE IF NOT EXISTS p0_products (id VARCHAR(64) PRIMARY KEY, name VARCHAR(100) NOT NULL, category VARCHAR(20) NOT NULL, description TEXT NOT NULL, scenario VARCHAR(255) NOT NULL, active BOOLEAN NOT NULL, image_url VARCHAR(255) NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS p0_skus (id VARCHAR(64) PRIMARY KEY, product_id VARCHAR(64) NOT NULL, name VARCHAR(100) NOT NULL, region VARCHAR(40) NOT NULL, zone VARCHAR(40) NOT NULL, cpu INT NOT NULL, memory_gb INT NOT NULL, base_cents BIGINT NOT NULL, disk_cents BIGINT NOT NULL, bandwidth_cents BIGINT NOT NULL, version INT NOT NULL, active BOOLEAN NOT NULL, capacity INT NOT NULL, reserved INT NOT NULL DEFAULT 0, allocated INT NOT NULL DEFAULT 0, adapter VARCHAR(20) NOT NULL DEFAULT 'SIMULATED', images VARCHAR(255) NOT NULL DEFAULT 'ubuntu-22,rocky-9', min_disk INT NOT NULL DEFAULT 40, max_disk INT NOT NULL DEFAULT 500, max_bandwidth INT NOT NULL DEFAULT 100, periods VARCHAR(64) NOT NULL DEFAULT '1,3,12', grace_days INT NOT NULL DEFAULT 7, refund_days INT NOT NULL DEFAULT 7, INDEX(product_id));
CREATE TABLE IF NOT EXISTS p0_price_versions (id VARCHAR(64) PRIMARY KEY, sku_id VARCHAR(64) NOT NULL, version INT NOT NULL, snapshot TEXT NOT NULL, created_at DATETIME(3) NOT NULL, UNIQUE(sku_id,version));
CREATE TABLE IF NOT EXISTS p0_quotes (id VARCHAR(64) PRIMARY KEY, user_id VARCHAR(64) NOT NULL, sku_id VARCHAR(64) NOT NULL, kind VARCHAR(20) NOT NULL, instance_id VARCHAR(64), config TEXT NOT NULL, snapshot TEXT NOT NULL, unit_cents BIGINT NOT NULL, total_cents BIGINT NOT NULL, quantity INT NOT NULL, months INT NOT NULL, expires_at DATETIME(3) NOT NULL, INDEX(user_id));
CREATE TABLE IF NOT EXISTS p0_orders (id VARCHAR(64) PRIMARY KEY, user_id VARCHAR(64) NOT NULL, quote_id VARCHAR(64) NOT NULL, idempotency_key VARCHAR(100) NOT NULL, request_hash CHAR(64) NOT NULL, sku_id VARCHAR(64) NOT NULL, kind VARCHAR(20) NOT NULL, instance_id VARCHAR(64), state VARCHAR(32) NOT NULL, config TEXT NOT NULL, snapshot TEXT NOT NULL, unit_cents BIGINT NOT NULL, total_cents BIGINT NOT NULL, refunded_cents BIGINT NOT NULL DEFAULT 0, refund_held_cents BIGINT NOT NULL DEFAULT 0, quantity INT NOT NULL, months INT NOT NULL, payment_deadline DATETIME(3) NOT NULL, created_at DATETIME(3) NOT NULL, UNIQUE(user_id,idempotency_key), INDEX(user_id,created_at), INDEX(state,payment_deadline));
CREATE TABLE IF NOT EXISTS p0_items (id VARCHAR(64) PRIMARY KEY, order_id VARCHAR(64) NOT NULL, user_id VARCHAR(64) NOT NULL, instance_id VARCHAR(64) NOT NULL, amount_cents BIGINT NOT NULL, state VARCHAR(32) NOT NULL, refunded BOOLEAN NOT NULL DEFAULT FALSE, refund_pending BOOLEAN NOT NULL DEFAULT FALSE, INDEX(order_id));
CREATE TABLE IF NOT EXISTS p0_payments (id VARCHAR(64) PRIMARY KEY, order_id VARCHAR(64) NOT NULL UNIQUE, user_id VARCHAR(64) NOT NULL, amount_cents BIGINT NOT NULL, channel VARCHAR(20) NOT NULL, state VARCHAR(32) NOT NULL, provider_id VARCHAR(64) UNIQUE, created_at DATETIME(3) NOT NULL, INDEX(user_id));
CREATE TABLE IF NOT EXISTS p0_payment_events (id VARCHAR(64) PRIMARY KEY, payment_id VARCHAR(64) NOT NULL, provider_id VARCHAR(64) NOT NULL UNIQUE, amount_cents BIGINT NOT NULL, outcome VARCHAR(32) NOT NULL, created_at DATETIME(3) NOT NULL);
CREATE TABLE IF NOT EXISTS p0_instances (id VARCHAR(64) PRIMARY KEY, user_id VARCHAR(64) NOT NULL, order_id VARCHAR(64) NOT NULL, sku_id VARCHAR(64) NOT NULL, name VARCHAR(100) NOT NULL, state VARCHAR(32) NOT NULL, config TEXT NOT NULL, provider_id VARCHAR(100) UNIQUE, public_ip VARCHAR(64), simulated BOOLEAN NOT NULL, created_at DATETIME(3) NOT NULL, starts_at DATETIME(3), expires_at DATETIME(3), grace_days INT NOT NULL, op_version INT NOT NULL DEFAULT 0, INDEX(user_id,created_at), INDEX(state,expires_at));
CREATE TABLE IF NOT EXISTS p0_tasks (id VARCHAR(64) PRIMARY KEY, business_key VARCHAR(150) NOT NULL UNIQUE, type VARCHAR(24) NOT NULL, order_id VARCHAR(64), instance_id VARCHAR(64), payload TEXT NOT NULL, state VARCHAR(32) NOT NULL, attempts INT NOT NULL DEFAULT 0, next_run DATETIME(3) NOT NULL, error VARCHAR(255), created_at DATETIME(3) NOT NULL, INDEX(state,next_run));
CREATE TABLE IF NOT EXISTS p0_outbox (id VARCHAR(64) PRIMARY KEY, event_key VARCHAR(150) NOT NULL UNIQUE, type VARCHAR(32) NOT NULL, payload TEXT NOT NULL, state VARCHAR(20) NOT NULL, attempts INT NOT NULL DEFAULT 0, next_run DATETIME(3) NOT NULL, INDEX(state,next_run));
CREATE TABLE IF NOT EXISTS p0_provider_resources (business_key VARCHAR(150) PRIMARY KEY, provider_id VARCHAR(100) NOT NULL UNIQUE, state VARCHAR(32) NOT NULL, expires_at DATETIME(3), updated_at DATETIME(3) NOT NULL);
CREATE TABLE IF NOT EXISTS p0_provider_payments (payment_id VARCHAR(64) PRIMARY KEY, transaction_id VARCHAR(64) NOT NULL UNIQUE, amount_cents BIGINT NOT NULL, state VARCHAR(20) NOT NULL, updated_at DATETIME(3) NOT NULL);
CREATE TABLE IF NOT EXISTS p0_provider_refunds (refund_id VARCHAR(64) PRIMARY KEY, transaction_id VARCHAR(64) NOT NULL UNIQUE, amount_cents BIGINT NOT NULL, state VARCHAR(20) NOT NULL);
CREATE TABLE IF NOT EXISTS p0_simulation_faults (business_key VARCHAR(150) PRIMARY KEY, mode VARCHAR(32) NOT NULL);
CREATE TABLE IF NOT EXISTS p0_renewals (order_id VARCHAR(64) PRIMARY KEY, instance_id VARCHAR(64) NOT NULL, old_expires DATETIME(3), new_expires DATETIME(3) NOT NULL, created_at DATETIME(3) NOT NULL);
CREATE TABLE IF NOT EXISTS p0_refunds (id VARCHAR(64) PRIMARY KEY, user_id VARCHAR(64) NOT NULL, order_id VARCHAR(64) NOT NULL, item_id VARCHAR(64) NOT NULL, amount_cents BIGINT NOT NULL, reason VARCHAR(500) NOT NULL, state VARCHAR(32) NOT NULL, review_reason VARCHAR(500), provider_id VARCHAR(100), created_at DATETIME(3) NOT NULL, INDEX(user_id,created_at));
CREATE TABLE IF NOT EXISTS p0_tickets (id VARCHAR(64) PRIMARY KEY, user_id VARCHAR(64) NOT NULL, type VARCHAR(24) NOT NULL, title VARCHAR(100) NOT NULL, order_id VARCHAR(64), instance_id VARCHAR(64), state VARCHAR(24) NOT NULL, assignee VARCHAR(64), created_at DATETIME(3) NOT NULL, INDEX(user_id,created_at));
CREATE TABLE IF NOT EXISTS p0_replies (id VARCHAR(64) PRIMARY KEY, ticket_id VARCHAR(64) NOT NULL, user_id VARCHAR(64) NOT NULL, staff BOOLEAN NOT NULL, content TEXT NOT NULL, created_at DATETIME(3) NOT NULL, INDEX(ticket_id));
CREATE TABLE IF NOT EXISTS p0_attachments (id VARCHAR(64) PRIMARY KEY, user_id VARCHAR(64) NOT NULL, ticket_id VARCHAR(64), name VARCHAR(150) NOT NULL, content_type VARCHAR(64) NOT NULL, bytes LONGBLOB NOT NULL, created_at DATETIME(3) NOT NULL, INDEX(ticket_id));
CREATE TABLE IF NOT EXISTS p0_notifications (id VARCHAR(64) PRIMARY KEY, user_id VARCHAR(64) NOT NULL, event_key VARCHAR(150) NOT NULL UNIQUE, title VARCHAR(100) NOT NULL, content VARCHAR(1000) NOT NULL, is_read BOOLEAN NOT NULL DEFAULT FALSE, created_at DATETIME(3) NOT NULL, INDEX(user_id,created_at));
CREATE TABLE IF NOT EXISTS p0_audits (id VARCHAR(64) PRIMARY KEY, actor_id VARCHAR(64) NOT NULL, action VARCHAR(64) NOT NULL, object_id VARCHAR(150) NOT NULL, detail VARCHAR(2000) NOT NULL, request_id VARCHAR(64) NOT NULL, created_at DATETIME(3) NOT NULL, INDEX(created_at));
CREATE TABLE IF NOT EXISTS p0_chat_sessions (id VARCHAR(64) PRIMARY KEY, user_id VARCHAR(64) NOT NULL, title VARCHAR(100) NOT NULL, deleted BOOLEAN NOT NULL DEFAULT FALSE, created_at DATETIME(3) NOT NULL, INDEX(user_id,created_at));
CREATE TABLE IF NOT EXISTS p0_chat_messages (id VARCHAR(64) PRIMARY KEY, session_id VARCHAR(64) NOT NULL, role VARCHAR(20) NOT NULL, content MEDIUMTEXT NOT NULL, created_at DATETIME(3) NOT NULL, INDEX(session_id,created_at));
CREATE TABLE IF NOT EXISTS p0_legacy_orders (id VARCHAR(64) PRIMARY KEY, legacy_user_id VARCHAR(64) NOT NULL, product_name VARCHAR(100) NOT NULL, amount_cents BIGINT NOT NULL, legacy_status VARCHAR(32) NOT NULL, provenance VARCHAR(40) NOT NULL DEFAULT 'HISTORICAL_IMPORT');
